(()=>{
 const app=document.querySelector('#app');
 if(!app||app.children.length)return;
 const step=location.hash.split('/')[1]||'signin';
 const style=document.createElement('style');
 style.textContent=`body{margin:0;background:linear-gradient(135deg,#f7f4ff,#fff3fa);font-family:Arial,sans-serif;color:#211238}body>.announcement,body>header,body>footer{display:none}.auth-lite{min-height:100vh;display:grid;place-items:center;padding:28px 18px}.auth-lite-card{width:min(410px,100%);background:#fff;border:1px solid #eadff3;border-radius:18px;box-shadow:0 18px 60px #5d267216;padding:32px}.auth-lite-logo{display:block;width:135px;height:92px;object-fit:contain;margin:0 auto 18px}.auth-lite h1{text-align:center;font-size:28px;margin:0 0 8px}.auth-lite-intro{text-align:center;color:#7d6b87;font-size:14px;line-height:1.6;margin:0 0 24px}.auth-lite-form{display:grid;gap:16px}.auth-lite-form label{display:grid;gap:7px;font-size:14px;font-weight:700}.auth-lite-form input{width:100%;box-sizing:border-box;border:1px solid #ddcfe7;border-radius:8px;padding:13px;font-size:15px}.auth-lite-button{display:flex;align-items:center;justify-content:center;border:0;border-radius:8px;padding:14px 18px;background:linear-gradient(105deg,#ed168d,#a72bd8);color:#fff;font-size:15px;font-weight:800;text-decoration:none;cursor:pointer}.auth-lite-secondary{background:#fff;color:#b11da1;border:1px solid #d9a4dc}.auth-lite-row{display:flex;justify-content:space-between;gap:12px;align-items:center;font-size:13px}.auth-lite-row a,.auth-lite-bottom a{color:#d51c91;font-weight:700;text-decoration:none}.auth-lite-bottom{text-align:center;color:#75637f;font-size:13px;margin:20px 0 0}.auth-lite-note{padding:11px;border-radius:7px;background:#fff6d9;color:#775e22;font-size:12px;line-height:1.55}.auth-lite-actions{display:grid;gap:10px}@media(max-width:480px){.auth-lite{padding:14px}.auth-lite-card{padding:25px 20px;border-radius:13px}.auth-lite h1{font-size:24px}}`;
 document.head.append(style);
 const logo='<img class="auth-lite-logo" src="assets/tura-logo.png?v=20261119-1" alt="TURA Infotech & Academy">';
 const shell=content=>`<section class="auth-lite"><div class="auth-lite-card">${logo}${content}</div></section>`;
 const signin=()=>shell(`<h1>Welcome back</h1><p class="auth-lite-intro">Sign in to continue to your user portal.</p><form class="auth-lite-form" id="auth-lite-signin"><label>Email address<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><div class="auth-lite-row"><label style="display:flex;grid-template-columns:auto 1fr;align-items:center;font-weight:400"><input style="width:auto" type="checkbox"> Remember me</label><a href="#auth/forgot">Forgot password?</a></div><p class="auth-lite-note">Interface preview: authentication is not connected yet.</p><button class="auth-lite-button">Open user portal preview</button></form><p class="auth-lite-bottom">New to TURA? <a href="#auth/signup">Create an account</a></p>`);
 const signup=()=>shell(`<h1>Create your account</h1><p class="auth-lite-intro">Enter your details to preview the user registration flow.</p><form class="auth-lite-form" id="auth-lite-signup"><label>Full name<input name="name" autocomplete="name" required></label><label>Email address<input name="email" type="email" autocomplete="email" required></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" required></label><label>Create password<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><p class="auth-lite-note">Preview only. No account or password will be stored.</p><button class="auth-lite-button">Preview registration</button></form><p class="auth-lite-bottom">Already registered? <a href="#auth/signin">Sign in</a></p>`);
 const forgot=()=>shell(`<h1>Reset your password</h1><p class="auth-lite-intro">Enter your registered email to preview the recovery flow.</p><form class="auth-lite-form" id="auth-lite-forgot"><label>Email address<input name="email" type="email" autocomplete="email" required></label><p class="auth-lite-note">No email will be sent in this interface preview.</p><button class="auth-lite-button">Continue</button></form><p class="auth-lite-bottom"><a href="#auth/signin">Back to sign in</a></p>`);
 const render=()=>{const route=location.hash.split('/')[1]||'signin';app.innerHTML=route==='signup'?signup():route==='forgot'?forgot():signin();document.querySelector('#auth-lite-signin')?.addEventListener('submit',event=>{event.preventDefault();location.href='portal.html?role=student#dashboard'});document.querySelector('#auth-lite-signup')?.addEventListener('submit',event=>{event.preventDefault();location.hash='auth/signin'});document.querySelector('#auth-lite-forgot')?.addEventListener('submit',event=>{event.preventDefault();location.hash='auth/signin'})};
 render();window.addEventListener('hashchange',render);
})();
